def chronological_fold(rows,start,end):
    # (sample_id,decision,feature_available,label_end,label_available,feature_value).
    if any(type(x) is not int for x in (start,end)) or not 0<=start<end or type(rows) is not list or len(rows)>128:
        raise ValueError("invalid fold boundary")
    seen=set()
    for row in rows:
        if type(row) is not tuple or len(row)!=6:raise ValueError("invalid sample schema")
        name,decision,feature_at,label_end,label_at,value=row
        if type(name) is not str or not name or name in seen or any(type(x) is not int for x in row[1:]):
            raise ValueError("invalid sample types or duplicate id")
        if not 0<=feature_at<=decision<=label_end<=label_at:
            raise ValueError("invalid sample information clocks")
        seen.add(name)
    train=[];test=[];excluded=[]
    for row in sorted(rows,key=lambda row:(row[1],row[0])):
        name,decision,feature_at,label_end,label_at,value=row
        if start<=decision<end:test.append(row)
        elif decision>=end:excluded.append((name,"after-test-window"))
        elif label_end>=start or label_at>=start:excluded.append((name,"training-label-not-known-before-test"))
        else:train.append(row)
    return tuple(train),tuple(test),tuple(excluded)

samples=[("a",1,1,2,2,10),("b",2,2,4,6,20),("c",4,4,7,8,30),("d",6,6,8,9,100),("e",8,8,9,9,200)]
train,test,excluded=chronological_fold(samples,6,8)
print(tuple(row[0] for row in train),tuple(row[0] for row in test))
print(excluded)
# Fit a centering constant on TRAIN only;test labels are for later scoring.
from fractions import Fraction
if not train:raise ValueError("no training rows")
mean=sum((Fraction(row[5]) for row in train),Fraction())/len(train)
print(mean,tuple(Fraction(row[5])-mean for row in test))
print(sum(Fraction(row[5]) for row in train+test)/len(train+test))
try:chronological_fold(samples+[("bad",3,4,5,5,10)],6,8)
except ValueError as error:print(error)
